#!/usr/bin/python3
# SPDX-License-Identifier: GPL-3.0-or-later
# verify_move.py - prove that the built `sbx` is the old single file, only rearranged.
#     git show OLD_COMMIT:sbx > /tmp/sbx.old && python3 tools/verify_move.py /tmp/sbx.old sbx
# Checks: (1) the same top-level statements, each with an identical syntax tree (positions ignored), none added or
# dropped; only their order may differ; (2) every non-blank line of the old file is in the new one, the same number
# of times, and the only extra line is the "GENERATED by build.py" notice.
import ast, collections, sys

def stmts(path):
    src = open(path).read()
    return src, collections.Counter(ast.dump(n, include_attributes=False) for n in ast.parse(src).body)

def main(old, new):
    so, ao = stmts(old); sn, an = stmts(new)
    ok = True
    print(f"top-level statements: old {sum(ao.values())}, new {sum(an.values())}")
    for label, d in (("in old only", ao - an), ("in new only", an - ao)):
        for k in d: ok = False; print(f"  AST MISMATCH ({label}): {k[:110]}...")
    print("  syntax trees identical statement by statement" if ao == an else "  syntax trees DIFFER")
    lo = collections.Counter(l for l in so.splitlines() if l.strip())
    ln = collections.Counter(l for l in sn.splitlines() if l.strip())
    missing, extra = lo - ln, ln - lo
    print(f"non-blank lines: old {sum(lo.values())}, new {sum(ln.values())}")
    for l, n in missing.items(): ok = False; print(f"  MISSING x{n}: {l[:110]}")
    for l, n in extra.items():
        print(f"  extra x{n}: {l[:110]}")
        if not l.startswith("# GENERATED by build.py"): ok = False
    print("OK: nothing lost, nothing changed" if ok else "FAILED")
    return 0 if ok else 1

if __name__ == "__main__":
    if len(sys.argv) != 3: sys.exit("usage: verify_move.py OLD NEW")
    sys.exit(main(*sys.argv[1:]))
